            <div className="flex items-start md:items-center justify-center p-4 sm:p-8 min-h-[calc(100vh-3.5rem)]">
               <ProjectDetailView 
                  {...selectedProject} 
                  onBack={() => setCurrentView('dashboard')}
                  onUpdate={handleUpdateProject}
               />
            </div>
        )}
      </main>
    </div>
  );
}

export default App;

import * as React from "react";
