interface DashboardProps {
    projects: Project[];
    onSelectProject: (project: Project) => void;
    onCreateProject: (project: Project) => void;
    onDeleteProject: (projectId: string) => void;
}

const StageProgressBar = ({ status }: { status: Stage }) => {
    const stages: Stage[] = ['Kickoff', 'In-Progress', 'Completed', 'Signed', 'Paid'];
    const currentIndex = stages.indexOf(status);

    return (
        <div className="flex items-center gap-1 w-full mt-3">
            {stages.map((stage, idx) => (
                <div key={stage} className="flex-1 flex flex-col items-center group">
                     <div 
                        className={cn(
                            "h-2 w-full rounded-full transition-all duration-500",
                            idx <= currentIndex 
                                ? "bg-primary" 
                                : "bg-muted"
                        )}
                        title={stage}
                    />
                </div>
            ))}
        </div>
    );
};

export const Dashboard = ({ projects, onSelectProject, onCreateProject, onDeleteProject }: DashboardProps) => {
    const [isCreateOpen, setIsCreateOpen] = React.useState(false);
    const [newProjectTitle, setNewProjectTitle] = React.useState("");
    const [newProjectClient, setNewProjectClient] = React.useState("");
    const [newProjectValue, setNewProjectValue] = React.useState("5000");

    const totalRevenue = projects
        .filter(p => p.status === 'Paid')
        .reduce((sum, p) => sum + p.value, 0);

    const pendingRevenue = projects
        .filter(p => p.status === 'Signed' || p.status === 'Completed')
        .reduce((sum, p) => sum + p.value, 0);

    const activeProjects = projects.filter(p => p.status !== 'Paid').length;

    const handleCreate = () => {
        if (!newProjectTitle || !newProjectClient) return;

        const newProject: Project = {
            id: Math.random().toString(36).substr(2, 9),
            title: newProjectTitle,
            client: newProjectClient,
            status: 'Kickoff',
            completionPercentage: 0,
            value: parseInt(newProjectValue) || 0,
            breadcrumbs: [{ label: "Client Projects", href: "#" }, { label: newProjectTitle, href: "#" }],
            assignees: [],
            dateRange: { start: new Date().toLocaleDateString(), end: "TBD" },
            tags: [],
            description: "New client project. Click to edit description and use Gemini to brainstorm tasks.",
            attachments: [],
            subTasks: []
        };

        onCreateProject(newProject);
        setIsCreateOpen(false);
        setNewProjectTitle("");
        setNewProjectClient("");
        setNewProjectValue("5000");
    };

    return (
        <div className="p-4 sm:p-8 space-y-8 max-w-7xl mx-auto">

            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-2">
                        <Icons.LayoutGrid className="h-8 w-8 text-primary" />
                        Client Projects
                    </h1>
                    <p className="text-muted-foreground mt-1">Manage your portfolio, track progress, and handle billing.</p>
                </div>
                <div className="flex gap-2">
                     <Button onClick={() => setIsCreateOpen(true)}>
                        <Icons.Plus className="h-4 w-4 mr-2" />
                        New Project
                    </Button>
                </div>
            </div>

            {/* Metrics */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Revenue (Paid)</CardTitle>
                        <Icons.DollarSign className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">${totalRevenue.toLocaleString()}</div>
                        <p className="text-xs text-muted-foreground">+20.1% from last month</p>
                    </CardContent>
                </Card>
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Pipeline (Pending)</CardTitle>
                        <Icons.Briefcase className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">${pendingRevenue.toLocaleString()}</div>
                        <p className="text-xs text-muted-foreground">In signed or completed contracts</p>
                    </CardContent>
                </Card>
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Active Projects</CardTitle>
                        <Icons.Activity className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{activeProjects}</div>
                        <p className="text-xs text-muted-foreground">Projects currently in progress</p>
                    </CardContent>
                </Card>
            </div>

            {/* Project Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {projects.map(project => (
                    <Card key={project.id} className="group hover:shadow-lg transition-all duration-300 border-l-4 border-l-transparent hover:border-l-primary cursor-pointer relative" onClick={() => onSelectProject(project)}>
                        <CardHeader className="pb-3">
                            <div className="flex justify-between items-start">
                                <div>
                                    <Badge variant="secondary" className="mb-2">{project.client}</Badge>
                                    <CardTitle className="text-lg">{project.title}</CardTitle>
                                </div>
                                <div className="p-2 opacity-0 group-hover:opacity-100 transition-opacity" onClick={(e) => { e.stopPropagation(); onDeleteProject(project.id); }}>
                                    <Icons.Trash2 className="h-4 w-4 text-muted-foreground hover:text-destructive" />
                                </div>
                            </div>
                            <CardDescription className="line-clamp-2">{project.description}</CardDescription>
                        </CardHeader>
                        <CardContent>
                            <div className="flex justify-between text-sm mb-2">
                                <span className="text-muted-foreground font-medium">{project.status}</span>
                                <span className="font-semibold">${project.value.toLocaleString()}</span>
                            </div>
                            <StageProgressBar status={project.status} />
                            <div className="mt-4 flex justify-between items-center">
                                <span className="text-xs text-muted-foreground">{project.subTasks.length} Tasks</span>
                                <span className="text-xs font-medium text-primary flex items-center">View Details <Icons.ArrowRight className="h-3 w-3 ml-1" /></span>
                            </div>
                        </CardContent>
                    </Card>
                ))}

                {/* Empty State / Add New */}
                <div 
                    className="border-2 border-dashed rounded-lg flex flex-col items-center justify-center p-8 text-muted-foreground hover:bg-muted/40 hover:text-foreground transition-colors cursor-pointer min-h-[200px]"
                    onClick={() => setIsCreateOpen(true)}
                >
                    <Icons.Plus className="h-10 w-10 mb-2 opacity-50" />
                    <p className="font-medium">Create New Project</p>
                </div>
            </div>

            {/* Create Modal */}
            {isCreateOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200" onClick={(e) => e.target === e.currentTarget && setIsCreateOpen(false)}>
                    <div className="w-full max-w-md bg-background rounded-lg border shadow-xl overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="p-6 pb-4 border-b">
                            <h3 className="text-lg font-semibold">Start New Project</h3>
                        </div>
                        <div className="p-6 space-y-4">
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Project Title</label>
                                <input className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm" value={newProjectTitle} onChange={e => setNewProjectTitle(e.target.value)} placeholder="e.g. Website Redesign" autoFocus />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Client Name</label>
                                <input className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm" value={newProjectClient} onChange={e => setNewProjectClient(e.target.value)} placeholder="e.g. Acme Corp" />
                            </div>
                             <div className="space-y-2">
                                <label className="text-sm font-medium">Estimated Value ($)</label>
                                <input className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm" type="number" value={newProjectValue} onChange={e => setNewProjectValue(e.target.value)} />
                            </div>
                        </div>
                        <div className="flex justify-end gap-2 p-6 pt-0">
                            <Button variant="outline" onClick={() => setIsCreateOpen(false)}>Cancel</Button>
                            <Button onClick={handleCreate}>Create Project</Button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

